"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "edge",
    "name": "api-gateway",
    "uid": "uid-deployment-api-gateway"
  },
  "params": {
    "container": "app",
    "liveness": {
      "initialDelaySeconds": 90
    }
  },
  "expected_effect": "The liveness probe will wait longer before checking, allowing the application to start properly.",
